def histogram(test):

    dict1={}
    list1=test.split(" ")
    t=0

    for i in list1:
        if(list1.count(i)>t) and i!='':
            t=list1.count(i)
    if t>0:
        for i in list1:
            if(list1.count(i)==t):

                dict1[i]=t
    return dict1

# Unit test for function histogram
def test_histogram():

output:
```python
def test_histogram():
    # most frequent single word
    assert histogram("a b a c a b") == {"a": 3}

    # tie for most frequent
    assert histogram("dog cat dog cat bird") == {"dog": 2, "cat": 2}

    # all words unique -> all returned with count 1
    assert histogram("a b c") == {"a": 1, "b": 1, "c": 1}

    # single word
    assert histogram("hello") == {"hello": 1}

    # empty string -> empty dict
    assert histogram("") == {}

    # only spaces -> empty dict
    assert histogram("   ") == {}

    # extra spaces are ignored
    assert histogram("a  a b") == {"a": 2}

    # case-sensitive
    assert histogram("A a A") == {"A": 2}
```

